body.theme-dark {
  --cf-ground: var(--cyriform-ground, #07080A);
  --cf-paper: var(--cyriform-paper, #0C0E13);
  --cf-raised: #12151D;
  --cf-hover: #1C2130;
  --cf-ink: #E8E3D9;
  --cf-bright: #FBF8F1;
  --cf-muted: #A5A8B2;
  --cf-faint: #9096A3;
