  --cf-accent: var(--cyriform-accent, #91ABFF);
  --cf-gold: var(--cyriform-gold, #C6A56F);
  --cf-oxblood: var(--cyriform-oxblood, #D695A7);
  --cf-success: var(--cyriform-success, #92BBA4);
  --cf-cobalt-pigment: #365ED8;
  --cf-oxblood-pigment: #76273A;
  --cf-gold-pigment: #A78555;
  --cf-code: var(--cyriform-code-bg, #12151D);
  --cf-selection: #283C69;
  --cf-shadow: 0 8px 28px -10px #0009;
  --cf-on-accent: #0C0E13;
  --cf-info: #91ABFF;
  --cf-tip: #9DBDBA;
  --cf-highlight-ink: #F5DFBB;
  --cf-highlight-bg: #514027;
  --cf-search: #645126;
}

body.theme-light {
  --cf-ground: var(--cyriform-ground, #E8E3D9);
  --cf-paper: var(--cyriform-paper, #FBF8F1);
  --cf-raised: #F0ECE3;
  --cf-hover: #E4E0D7;
  --cf-ink: #24262B;
  --cf-bright: #14171C;
  --cf-muted: #5E6068;
  --cf-faint: #5E6068;
  --cf-rule: var(--cyriform-rule, #C9C1B2);
  --cf-accent: var(--cyriform-accent, #3156C9);
  --cf-gold: var(--cyriform-gold, #795722);
  --cf-oxblood: var(--cyriform-oxblood, #76273A);
  --cf-success: var(--cyriform-success, #35644E);
  --cf-cobalt-pigment: #365ED8;
  --cf-oxblood-pigment: #76273A;
  --cf-gold-pigment: #A78555;
  --cf-code: var(--cyriform-code-bg, #EEE9DE);
  --cf-selection: #DCE3F7;
  --cf-shadow: 0 8px 28px -12px #31291E40;
  --cf-on-accent: #FFFFFF;
