  --cf-highlight-ink: #342B18;
  --cf-highlight-bg: #F0D69D;
  --cf-search: #F0D69D;
}

body {
  --cf-read: var(--cyriform-font-reading, "EB Garamond", Georgia, serif);
  --cf-display: var(--cyriform-font-heading, "Cormorant Garamond", Georgia, serif);
  --cf-ui: var(--cyriform-font-interface, "Beiruti", system-ui, sans-serif);
  --cf-mono: var(--cyriform-font-code, "IBM Plex Mono", "JetBrains Mono", Menlo, Consolas, monospace);
  --cf-radius: var(--cyriform-radius, 3px);
  --cf-border: var(--cyriform-border-width, 1px);
  --cf-row: 30px;
  --cf-speed: var(--cyriform-motion-duration, 160ms);
  --font-text-theme: var(--cf-read);
  --font-text: var(--cf-read);
  --font-interface-theme: var(--cf-ui);
  --font-interface: var(--cf-ui);
  --font-monospace-theme: var(--cf-mono);
  --font-monospace: var(--cf-mono);
  --font-text-size: var(--cyriform-text-size, 19px);
  --font-ui-medium: var(--cyriform-ui-size, 16px);
