  --background-modifier-border: var(--cf-rule);
  --background-modifier-border-hover: var(--cf-muted);
  --background-modifier-border-focus: var(--cf-accent);
  --background-modifier-form-field: var(--cf-paper);
  --background-modifier-message: var(--cf-raised);
  --background-modifier-error: var(--cf-oxblood-pigment);
  --background-modifier-success: var(--cf-success);
  --text-normal: var(--cf-ink);
  --text-muted: var(--cf-muted);
  --text-faint: var(--cf-faint);
  --text-accent: var(--cf-accent);
